window.HOEREN_TESTS[25] = {"id":"friseur-und-schoenheit","name":"Friseur und Schönheit","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Hallo Frau Müller, hier ist der Friseursalon Schön. Ihr Termin am Donnerstag um 14 Uhr — wir müssen ihn leider verschieben. Donnerstag um 14 Uhr geht also nicht. Statt 14 Uhr können Sie um 16 Uhr kommen, oder ich biete Ihnen Freitag um 10 Uhr an. Erst nächste Woche muss es nicht sein. Bitte rufen Sie zurück bis morgen, dann halten wir den Platz frei.","gender":"f","q":"Welche Termine sind möglich?","opts":["Donnerstag um 14 Uhr.","Erst nächste Woche.","Donnerstag um 16 Uhr oder Freitag um 10 Uhr."],"correct":2},{"transcript":"Liebe Kundinnen, willkommen im Beauty-Salon Belle. Heute haben wir Sonderpreise: Maniküre 25 statt 35 Euro, Pediküre 30 statt 40 Euro. Massage haben wir auch günstig — 50 Minuten für 45 Euro. Aber Gesichtsbehandlung bleibt zum normalen Preis von 80 Euro, ohne Sonderpreis. Maniküre und Pediküre sind also günstiger, die Gesichtsbehandlung nicht. Fragen Sie uns gern an der Rezeption.","gender":"f","q":"Welche Behandlung hat keinen Sonderpreis?","opts":["Maniküre.","Pediküre.","Gesichtsbehandlung."],"correct":2},{"transcript":"Hi Schatz, hier ist Anna. Hör mal, ich bin gerade beim Friseur und es dauert länger als gedacht — vielleicht eine Stunde mehr. Geh schon vor zum Restaurant, ich komme nach. Bestell schon den Wein, mein Lieblings-Rotwein vom letzten Mal. Bis später! Ich beeile mich, versprochen!","gender":"f","q":"Was soll der Mann tun?","opts":["Auf Anna beim Friseur warten.","Vor zum Restaurant gehen.","Den Termin verschieben."],"correct":1},{"transcript":"Achtung an alle Kundinnen: Unser Friseursalon ist morgen am Mittwoch geschlossen wegen Fortbildung der Mitarbeiterinnen. Also kein normaler Tag und keine Sonderöffnung. Donnerstag und Freitag sind wir wieder offen. Wer einen dringenden Termin hat, kann zum Schwestersalon in der Marktstraße — dort haben wir Plätze freigemacht. Danke für Ihr Verständnis.","gender":"m","q":"Was ist morgen?","opts":["Der Salon ist geschlossen.","Normaler Tag.","Sonderöffnung."],"correct":0},{"transcript":"Hallo Lisa, hier ist deine Friseurin Maria. Ich denke nochmal an den neuen Schnitt, den wir besprochen haben — etwas Mutigeres, kürzer als jetzt. Aber ich brauche dein Foto-Vorbild bis morgen, sonst nehme ich Standard-Schnitt. Bitte schick mir was per WhatsApp. Beeil dich bitte, danke!","gender":"f","q":"Was soll Lisa schicken?","opts":["Den Termin bestätigen.","Ein Foto-Vorbild für den Schnitt.","Das Geld."],"correct":1}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer macht was? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Sara","gender":"f","text":"Hallo Anna! Hast du am Freitag Zeit für den Salon?"},{"speaker":"Anna","gender":"f","text":"Hallo Sara! Ich habe endlich frei und warte schon lange auf den Termin."},{"speaker":"Sara","gender":"f","text":"Ich mache eine neue Frisur. Kurz und modern steht mir besser."},{"speaker":"Anna","gender":"f","text":"Kurz passt gut zu deinen Augen. Das wird richtig hübsch."},{"speaker":"Sara","gender":"f","text":"Färbt noch jemand die Haare blond?"},{"speaker":"Anna","gender":"f","text":"Nein. Niemand färbt die Haare."},{"speaker":"Sara","gender":"f","text":"Ich sehe Nagellack in deiner Tasche. Was hast du damit vor?"},{"speaker":"Anna","gender":"f","text":"Ich mache eine Maniküre in Dunkelrot. Die Farbe passt zum Kleid."},{"speaker":"Sara","gender":"f","text":"Lisa arbeitet in letzter Zeit einfach viel zu lange im Büro."},{"speaker":"Anna","gender":"f","text":"Lisa bekommt eine Gesichtsbehandlung. Danach ist sie wieder ganz ruhig."},{"speaker":"Sara","gender":"f","text":"Sophie heiratet in zwei Wochen. Was macht sie davor?"},{"speaker":"Anna","gender":"f","text":"Sophie lässt die Wimpern schwarz und lang verlängern."},{"speaker":"Sara","gender":"f","text":"Bleibt noch Zeit für eine Pediküre?"},{"speaker":"Anna","gender":"f","text":"Nein. Für eine Pediküre bleibt auch keine Zeit."},{"speaker":"Sara","gender":"f","text":"Mara klagt seit Tagen über den Rücken."},{"speaker":"Anna","gender":"f","text":"Mara geht zur Massage. Eine ganze Stunde reicht ihr völlig."},{"speaker":"Sara","gender":"f","text":"Wir treffen uns um elf im Salon."},{"speaker":"Anna","gender":"f","text":"Ich freue mich schon sehr auf unseren gemeinsamen Termin."}],"options":[{"letter":"a","text":"macht eine neue Frisur"},{"letter":"b","text":"färbt die Haare"},{"letter":"c","text":"macht eine Pediküre"},{"letter":"d","text":"lässt Wimpern verlängern"},{"letter":"e","text":"geht zur Massage"},{"letter":"f","text":"bekommt Make-up gemacht"},{"letter":"g","text":"macht eine Sauna"},{"letter":"h","text":"bekommt eine Gesichtsbehandlung"},{"letter":"i","text":"macht eine Maniküre"}],"items":[{"person":"Sara","correct":"a"},{"person":"Anna","correct":"i"},{"person":"Lisa","correct":"h"},{"person":"Sophie","correct":"d"},{"person":"Mara","correct":"e"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Friseur","gender":"m","text":"Guten Tag, was wünschen Sie heute — Haare, Bart, oder beides?"},{"speaker":"Kunde","gender":"m","text":"Nur waschen und schneiden, etwa 2 Zentimeter ab. Nicht den Bart extra."},{"speaker":"Friseur","gender":"m","text":"Mit dem Bart auch was machen? Trimmen oder rasieren, oder wirklich nur die Haare?"},{"speaker":"Kunde","gender":"m","text":"Nein, Bart lasse ich so. Nur die Haare, nicht Bart und Haare zusammen."},{"speaker":"Friseur","gender":"m","text":"Alles klar, nur Haare. Setzen Sie sich bitte, ich hole das Handtuch."}],"q":"Was lässt der Kunde machen?","opts":["Nur Haare.","Nur Bart.","Bart und Haare."],"correct":0},{"lines":[{"speaker":"Kundin","gender":"f","text":"Guten Tag, ich möchte eine andere Haarfarbe. Rot, heller, oder dunkler?"},{"speaker":"Friseurin","gender":"f","text":"Welche Richtung? Heller oder dunkler? Rot wäre auch möglich."},{"speaker":"Kundin","gender":"f","text":"Eigentlich wollte ich rot. Aber das ist mir zu mutig. Dunkler mag ich auch nicht."},{"speaker":"Friseurin","gender":"f","text":"Dann lieber ein etwas helleres Braun? Subtiler als rot, nicht dunkler."},{"speaker":"Kundin","gender":"f","text":"Ja, helleres Braun ist gut. Nicht rot und nicht dunkler."}],"q":"Welche Haarfarbe wählt sie?","opts":["Rot.","Helleres Braun.","Dunkler."],"correct":1},{"lines":[{"speaker":"Kundin","gender":"f","text":"Guten Tag, was kostet eine Maniküre? 25, 35 oder 50 Euro?"},{"speaker":"Mitarbeiterin","gender":"f","text":"Klassisch 25 Euro, mit Nagellack 35 Euro, mit Nail-Art 50 Euro. Was darf es sein?"},{"speaker":"Kundin","gender":"f","text":"Ohne Lack ist 25, das ist mir zu schlicht. Nail-Art für 50 ist zu teuer. Mit Nagellack bitte, also 35 Euro."},{"speaker":"Mitarbeiterin","gender":"f","text":"Gerne, Maniküre mit Lack für 35 Euro. Welche Farbe möchten Sie?"},{"speaker":"Kundin","gender":"f","text":"Ein helles Rosa bitte. Danke, 35 Euro ist okay."}],"q":"Wie viel zahlt die Kundin?","opts":["50 Euro.","25 Euro.","35 Euro."],"correct":2},{"lines":[{"speaker":"Mann","gender":"m","text":"Was machst du nach der Arbeit? Bist du vor 18 Uhr zu Hause, oder später?"},{"speaker":"Frau","gender":"f","text":"Beauty-Salon. Eine Gesichtsbehandlung, dann Massage. Morgen ist das nicht."},{"speaker":"Mann","gender":"m","text":"Das dauert lange! Wann bist du zu Hause — vor 18, vor 20, oder erst morgen?"},{"speaker":"Frau","gender":"f","text":"Nicht vor 20 Uhr. Lass uns spät essen. Vor 18 Uhr schaffe ich es nicht, und morgen bleibe ich nicht dort."},{"speaker":"Mann","gender":"m","text":"Okay, dann esse ich später. Bis nach 20 Uhr, verstanden."}],"q":"Wann ist die Frau zu Hause?","opts":["Vor 18 Uhr.","Nicht vor 20 Uhr.","Erst morgen."],"correct":1},{"lines":[{"speaker":"Tochter","gender":"f","text":"Mama, kann ich mir die Ohren stechen lassen? Bitte sag nicht für immer nein."},{"speaker":"Mutter","gender":"f","text":"Du bist erst 10. Lass uns das ein bisschen aufschieben. Sofort ja sage ich nicht."},{"speaker":"Tochter","gender":"f","text":"Bis wann? Mit 12, oder wirklich niemals?"},{"speaker":"Mutter","gender":"f","text":"Bis du 12 bist. Dann reden wir nochmal. Nicht sofort, und auch nicht für immer."},{"speaker":"Tochter","gender":"f","text":"Okay, mit 12 nochmal reden. Das ist fair, danke Mama."}],"q":"Was sagt die Mutter?","opts":["Mit 12 nochmal reden.","Niemals.","Sofort ja."],"correct":0}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Becker, einer Friseurin. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Becker, Sie sind seit 25 Jahren Friseurin. Wie sind Sie zu diesem Beruf gekommen?"},{"speaker":"Becker","gender":"f","text":"Ich habe als 16-Jährige die Haare meiner Freundinnen geschnitten — kostenlos natürlich. Sie sagten alle, ich sei begabt. Also habe ich nach der Schule die Ausbildung gemacht. Lehrerin werden wollte ich auch, aber das war zu lang."},{"speaker":"Reporter","gender":"m","text":"Was lieben Sie an diesem Beruf?"},{"speaker":"Becker","gender":"f","text":"Der Kontakt zu Menschen. Frauen erzählen mir viel über ihr Leben, während sie auf dem Stuhl sitzen. Ich bin oft mehr Psychologin als Friseurin. Aber das macht mir Spaß."},{"speaker":"Reporter","gender":"m","text":"Was sind Ihre Arbeitszeiten?"},{"speaker":"Becker","gender":"f","text":"Dienstag bis Samstag, Montag ist Ruhetag wie in vielen Salons. Ich beginne um 9 Uhr morgens und arbeite bis 19 Uhr. Am Samstag bis 16 Uhr — meine kürzeste Schicht."},{"speaker":"Reporter","gender":"m","text":"Gibt es viele schwierige Kunden?"},{"speaker":"Becker","gender":"f","text":"Manchmal. Vor allem bei Färbungen — manche Kunden sind nie ganz zufrieden. Aber meistens kann ich mit Geduld und einem Lächeln alles lösen. Schwierige sind eher die Ausnahme."},{"speaker":"Reporter","gender":"m","text":"Schneiden Sie auch Ihre eigenen Haare?"},{"speaker":"Becker","gender":"f","text":"Niemals! Das ist eine alte Regel im Friseur-Beruf — eigene Haare lässt man von einer Kollegin schneiden. Selbst sieht man sich nie gut von hinten."}],"items":[{"q":"Sie arbeitet auch montags.","correct":"nein"},{"q":"Sie wollte auch Lehrerin werden.","correct":"ja"},{"q":"Frau Becker hat als Teenagerin schon Haare geschnitten.","correct":"ja"},{"q":"Färbungen sind oft Anlass für Beschwerden.","correct":"ja"},{"q":"Sie schneidet ihre eigenen Haare selbst.","correct":"nein"}]}]};
